fn settle_leg(
    from: &AccountInfo,
    to: &AccountInfo,
    authority: &AccountInfo,
    amount: u64,
    token_prog: &AccountInfo, // caller-chosen
) -> ProgramResult {
    // allowlist exists elsewhere but is NOT called on this path
    let mut ix = spl_token::instruction::transfer(
        &spl_token::ID, // hardcoded Tokenkeg — looks safe
        from.key,
        to.key,
        authority.key,
        &[],
        amount,
    )?;
    // --- critical line: trust boundary collapse ---
    ix.program_id = *token_prog.key;
    invoke(&ix, &[from.clone(), to.clone(), authority.clone(), token_prog.clone()])
}
